\text{2. Kecukupan Pengungkapan} & \text{(Full Disclosure memadai pada CaLK)} \\
\text{3. Kepatuhan Peraturan} & \text{(Bebas dari kerugian negara dan korupsi material)} \\
\text{4. Efektivitas SPI} & \text{(Sistem Pengendalian Intern pemerintah handal)}
\end{cases}

\text{Alokasi Dana Bantuan Parpol (Permendagri 78/2020)}:
\begin{cases}
\text{Pendidikan Politik Kader} & \ge 60\% \times \text{Total Bantuan APBN / APBD} \\
\text{Operasional Sekretariat} & \le 40\% \times \text{Total Bantuan APBN / APBD}
\end{cases}
